CREATE OR REPLACE FUNCTION public.account_session_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.account_access a WHERE a.user_id=auth.uid() AND NOT a.blocked AND (a.revoked_before IS NULL OR EXISTS(SELECT 1 FROM auth.sessions s WHERE s.user_id=a.user_id AND s.id=(auth.jwt()->>'session_id')::uuid AND s.created_at>a.revoked_before) OR ((auth.jwt()->>'session_id') IS NULL AND to_timestamp((auth.jwt()->>'iat')::double precision)>a.revoked_before))); $$;